import{_ as a,o as t,c as i,a4 as s}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"How Changeouts Flow","description":"","frontmatter":{"title":"How Changeouts Flow"},"headers":[],"relativePath":"excel/how-changeouts-flow.md","filePath":"excel/how-changeouts-flow.md","lastUpdated":null}'),l={name:"excel/how-changeouts-flow.md"};function n(o,e,r,d,h,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="how-changeouts-flow-pull-→-build-→-preview-→-push" tabindex="-1">How changeouts flow (pull → build → preview → push) <a class="header-anchor" href="#how-changeouts-flow-pull-→-build-→-preview-→-push" aria-label="Permalink to &quot;How changeouts flow (pull → build → preview → push)&quot;">​</a></h1><p>Step-by-step for running the CLI using the Excel wireframe.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Excel file in the expected location (or Smartsheet configured). See <a href="/ocapi-docs.github.io/config/">Configuration</a> and <a href="/ocapi-docs.github.io/guides/env-and-auth.html">Environment Setup</a>.</li><li><code>make setup</code> and <code>make pull</code> run successfully at least once.</li></ul><h2 id="_1-pull-fetch-and-pick-date" tabindex="-1">1. Pull (fetch and pick date) <a class="header-anchor" href="#_1-pull-fetch-and-pick-date" aria-label="Permalink to &quot;1. Pull (fetch and pick date)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Syncs with Git, fetches from Excel/Smartsheet, writes refresh JSONs under <code>dev-env/{brand}/refreshes/{date}/r#/</code>.</li><li>Shows a status table and an interactive date picker. The date you pick becomes the <strong>sticky</strong> selection for the next commands.</li></ul><h2 id="_2-build" tabindex="-1">2. Build <a class="header-anchor" href="#_2-build" aria-label="Permalink to &quot;2. Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Generates HTML and OCAPI payload for the <strong>selected</strong> date/refresh. Output is under the same <code>.../refreshes/{date}/r#/</code> folder (and preview subfolder).</li><li>If the guard says &quot;Already built&quot; or &quot;Already synced&quot;, use <code>make build FORCE=1</code> only when you need to regenerate (e.g. after template or Excel changes).</li></ul><h2 id="_3-preview" tabindex="-1">3. Preview <a class="header-anchor" href="#_3-preview" aria-label="Permalink to &quot;3. Preview&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Composes zones and prints preview URLs. Open them in the browser to verify content before pushing.</li></ul><h2 id="_4-push-validate-and-sync-to-sfcc" tabindex="-1">4. Push (validate and sync to SFCC) <a class="header-anchor" href="#_4-push-validate-and-sync-to-sfcc" aria-label="Permalink to &quot;4. Push (validate and sync to SFCC)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Runs data quality checks, then syncs to SFCC staging. Requires OCAPI to be enabled and configured.</li></ul><h2 id="what-to-do-if" tabindex="-1">What to do if… <a class="header-anchor" href="#what-to-do-if" aria-label="Permalink to &quot;What to do if…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What to do</th></tr></thead><tbody><tr><td>No refreshes after pull</td><td>Check Excel path and sheet format; see <a href="./wireframe-format.html">Wireframe format</a>.</td></tr><tr><td>&quot;Already built&quot; but you changed Excel/template</td><td><code>make build FORCE=1</code>.</td></tr><tr><td>Data quality errors on push</td><td>Fix issues in Excel (see <a href="./validation-and-fixes.html">Validation and fixes</a>), then <code>make pull</code>, <code>make build</code>, <code>make push</code> again.</td></tr><tr><td>Need to work on another date</td><td><code>make select DATE=YYYY-MM-DD/r1</code> (or use the picker when you run <code>make status</code> or <code>make pull</code>).</td></tr></tbody></table><h3 id="example-missing-destination-error" tabindex="-1">Example: &quot;Missing destination&quot; error <a class="header-anchor" href="#example-missing-destination-error" aria-label="Permalink to &quot;Example: &quot;Missing destination&quot; error&quot;">​</a></h3><p>If push fails with <strong>Missing destination</strong> (or a link/destination required message):</p><ol><li>Open the Excel wireframe and find the row(s) that have ACTION=LAUNCH (or a link) but an empty <strong>DESTINATION ID</strong> (or link) column.</li><li>Fill in the destination: category path (e.g. <code>/sale/winter</code>), full URL, or product ID as required by your asset type.</li><li>Save the Excel file, then run: <code>make pull</code> → <code>make build</code> → <code>make push</code>.</li></ol>',21)])])}const b=a(l,[["render",n]]);export{p as __pageData,b as default};
